// Biomedical Debate Practice Test 1. Original questions written for Valus on the 2026–27 resolution,
// "Limited healthcare resources should be allocated to patients with the greatest likelihood of
// long-term survival." Slightly harder than the sample items. Content follows the Valus Biomedical
// Debate lessons and the published allocation literature they cite.
import {q, mix} from './q.js';
const LEVY='Levy, Breaking the Age Code (2022)', BH='Bognar & Hirose, The Ethics of Health Care Rationing', EMAN='Emanuel et al., NEJM (2020)', PERSAD='Persad, Wertheimer & Emanuel, The Lancet (2009)', OPTN='Organ Procurement and Transplantation Network';
const SCAR='Scarcity and Levels of Allocation', ETH='Ethical Theories and Principles', CRIT='Allocation Criteria and Frameworks', CASE='Real-World Allocation Cases', AGE='Aging, Longevity and Equity';

export default {
 id:'biomedical-debate-1',
 event:'Biomedical Debate',
 title:'Practice Test 1',
 subtitle:'Round One test simulation on the 2026–27 resolution',
 minutes:60,
 sources:'Levy’s Breaking the Age Code, Bognar and Hirose’s The Ethics of Health Care Rationing and published allocation frameworks',
 plan:[{area:'Resolution: Allocating Limited Healthcare Resources',weight:100,topics:[SCAR,ETH,CRIT,CASE,AGE]}],
 questions:mix([
  q(SCAR,'A hospital decides which department absorbs the largest budget cut. At which level is this allocation decision made?','Meso',['Micro','Macro','Global'],'B','Micro decisions are about individual patients, meso decisions are made by institutions and macro decisions are made by governments or insurers.',BH),
  q(SCAR,'A physician chooses which of two patients receives the last ICU bed. What level of allocation is this?','Micro',['Meso','Macro','Systemic'],'D','Bedside choices between identifiable patients are micro-level decisions, the hardest to make without a policy.',BH),
  q(SCAR,'A state legislature divides its health budget between prevention programs and chronic care. What level of allocation is this?','Macro',['Micro','Meso','Clinical'],'A','Macro decisions set how much society spends on broad categories of care.',BH),
  q(SCAR,'A published organ allocation policy that states who qualifies and in what order is an example of:','Explicit rationing',['Implicit rationing','Absolute abundance','Market pricing only'],'C','Explicit rationing uses openly stated rules; implicit rationing happens through waits, costs and clinician judgment.',BH),
  q(SCAR,'Long waiting lists to see specialists are an example of:','Implicit rationing',['Explicit rationing','Absolute scarcity','A triage protocol'],'B','Care is limited without a stated rule; access depends on time, insurance and geography.',BH),
  q(SCAR,'Why are deceased-donor organs described as an absolute (not relative) scarcity?','More money cannot create more of them',['They are cheap to produce in bulk','Their price is set by the market','Any hospital can manufacture them'],'D','Relative scarcity can be eased by spending more; absolute scarcity cannot, which makes allocation rules unavoidable.',BH),
  q(SCAR,'Why do many crisis frameworks use a separate triage officer or committee instead of the treating physician?','To limit bias and protect the care relationship',['To speed up the admission paperwork for families','To let families make the final treatment choice','To avoid using any written criteria'],'A','Separating the roles lets the treating clinician remain the patient’s advocate while triage decisions stay consistent.',EMAN),
  q(SCAR,'Insurance prior authorization requirements are best described as:','Everyday implicit rationing',['A macro-level vaccine policy','A form of absolute scarcity','A purely clinical diagnosis'],'C','They limit use of services without an openly stated rationing rule applied to each patient.',BH),
  q(ETH,'Which ethical theory most directly supports allocating resources to save the most life-years?','Utilitarianism',['Egalitarianism','Prioritarianism','Libertarianism'],'B','Utilitarianism aims to maximize total benefit, which supports the affirmative’s focus on long-term survival.',BH),
  q(ETH,'A lottery among all eligible patients best reflects which theory?','Egalitarianism',['Utilitarianism','Prioritarianism','Ethical egoism'],'D','Lotteries treat each person as having an equal claim, regardless of expected benefit.',BH),
  q(ETH,'Which theory gives extra moral weight to benefits that go to the worst off?','Prioritarianism',['Utilitarianism','Contractarianism','Virtue ethics'],'A','Prioritarians weigh benefits more heavily the worse off the recipient is, which can support treating the sickest first.',BH),
  q(ETH,'A treatment adds 4 years of life at a quality weight of 0.5. How many QALYs does it produce?','2',['0.5','4','8'],'C','QALYs = years × quality weight = 4 × 0.5 = 2. One year in full health equals 1 QALY.',BH),
  q(ETH,'A common critique that QALY-based allocation is unfair to people with disabilities rests on what point?','Lower quality weights shrink their claims',['QALYs ignore length of life entirely','QALYs count only patients over 65','QALYs are calculated by lottery'],'B','Because a disability can lower the quality weight, the same life-saving treatment may appear to produce fewer QALYs.',BH),
  q(ETH,'The “fair innings” argument gives priority to which patients?','Those who have lived fewer years',['Those with the most money','Those who arrived first','Those with the most dependents'],'D','Everyone deserves a chance at a normal lifespan, so younger patients who have not had their innings come first.',BH),
  q(ETH,'Which principle of biomedical ethics concerns the fair distribution of benefits and burdens?','Justice',['Autonomy','Beneficence','Nonmaleficence'],'A','Distributive justice is the central principle in rationing debates.',BH),
  q(ETH,'Daniels’ “aggregation problem” asks:','When many small benefits outweigh a large one',['Whether patients can consent to triage','How to count organ donors each year','Which hospital should set budgets'],'C','For example, whether treating many people with minor conditions outweighs saving one life.',BH),
  q(ETH,'The “rule of rescue” describes the tendency to:','Spend heavily to save identified people',['Treat only patients who can pay','Rescue the oldest patients first','Ignore people in immediate danger'],'B','People feel strongly obligated to save identifiable lives in danger, even when cost-effectiveness would favor other uses.',BH),
  q(ETH,'A common critique of strictly utilitarian allocation is that it:','Can ignore how benefits are distributed',['Always favors the sickest patients','Requires random selection of patients','Cannot use any medical evidence'],'D','Maximizing totals can leave some groups consistently disadvantaged, raising fairness and equity objections.',BH),
  q(CRIT,'Which criterion belongs to the “maximize benefits” family?','Save the most life-years',['Sickest first','First come, first served','Youngest first'],'A','Maximizing lives or life-years saved is a benefit criterion; sickest-first and youngest-first favor the worst off.',PERSAD),
  q(CRIT,'Which allocation criterion falls under “favoring the worst off”?','Sickest first',['Prognosis','Instrumental value','Save the most lives'],'C','Sickest-first and youngest-first both give priority to those who are worse off now or over a lifetime.',PERSAD),
  q(CRIT,'What did Persad, Wertheimer and Emanuel conclude about single allocation principles?','None is sufficient on its own',['Lottery alone is always fair','First come is the best rule','Prognosis alone is decisive'],'B','They proposed a “complete lives system” that combines youngest-first, prognosis, saving the most lives and lotteries.',PERSAD),
  q(CRIT,'Emanuel et al. (2020) recommended against which allocation method during COVID-19?','First come, first served',['Random selection among equals','Priority to health care workers','Maximizing benefits'],'D','First come, first served favors people with better access and does not maximize benefit.',EMAN),
  q(CRIT,'According to Emanuel et al., among patients with similar prognoses, how should scarce resources be allocated?','By random selection',['By ability to pay','By hospital seniority','By time of arrival'],'A','A lottery treats equals equally once benefit considerations no longer distinguish patients.',EMAN),
  q(CRIT,'What do SOFA scores measure in many crisis triage protocols?','Severity of organ failure',['Donor kidney quality','Age-adjusted life expectancy','Hospital bed occupancy'],'C','The Sequential Organ Failure Assessment estimates short-term survival in ICU patients.',EMAN),
  q(CRIT,'Under Daniels and Sabin’s “accountability for reasonableness,” rationing decisions must be:','Public, relevant and open to appeal',['Secret to prevent lawsuits','Set by each doctor at the bedside','Decided only by insurers'],'B','The conditions are publicity, relevance, revisability with appeals, and enforcement.',BH),
  q(CRIT,'Emanuel et al. argued for priority to front-line health workers mainly because of:','Instrumental value',['Their younger age','Their higher income','Their political influence'],'D','Keeping health workers able to work saves more lives overall, and it rewards those who take on risk.',EMAN),
  q(CRIT,'Which approach would most directly put the resolution into practice?','Prioritizing by expected long-term survival',['Treating patients in order of arrival','Selecting all patients by a lottery','Giving priority to the sickest patients'],'A','The affirmative ranks patients by likelihood of long-term survival; the other options are rival criteria.',PERSAD),
  q(CRIT,'A negative team argues that long-term prognosis is often inaccurate for individuals. Which alternative is it likely to propose?','A short-term benefit threshold, then a lottery',['First come, first served for all patients','Allocation by ability to pay for care','Allocation only to the youngest patients'],'C','This keeps a minimum chance of benefit but avoids ranking patients by uncertain long-term predictions.',BH),
  q(CRIT,'Why must an affirmative team define “long-term survival” as individualized and evidence-based?','To avoid using age or disability as stand-ins',['To exclude all patients over 50','To rely only on a doctor’s intuition','To keep the criteria hidden from the public'],'B','Blanket categories invite discrimination claims; patient-specific clinical evidence is more defensible.',EMAN),
  q(CASE,'Which organization sets U.S. deceased-donor organ allocation policy?','The OPTN',['The FDA','The CDC','The WHO'],'D','The Organ Procurement and Transplantation Network, operated under federal contract, writes allocation policy.',OPTN),
  q(CASE,'In kidney allocation, what does the KDPI describe?','Donor kidney quality and longevity',['Recipient insurance coverage type','Distance to the hospital','The surgeon’s experience'],'A','A lower Kidney Donor Profile Index means a kidney is expected to function longer.',OPTN),
  q(CASE,'U.S. kidney “longevity matching” directs the best donor kidneys to which candidates?','The top 20% by expected survival',['Those who have waited the shortest time','Those with the highest incomes','Those over age 70 only'],'C','Candidates with the top 20% EPTS scores get priority for kidneys with KDPI of 20% or less, an established practice that supports the affirmative.',OPTN),
  q(CASE,'Why did several U.S. states revise their COVID-19 crisis standards of care?','Disability discrimination complaints',['A surplus of ventilators','Demands to use first come first served','A ban on all triage committees'],'B','Federal civil rights guidance warned against categorical exclusions based on disability or age.',EMAN),
  q(CASE,'What are crisis standards of care?','Plans for care when resources are overwhelmed',['Standards for routine annual checkups','Rules for hospital billing practices','Guidelines for elective cosmetic surgery'],'D','They shift care from the individual patient toward the best outcomes for the population during disasters.',EMAN),
  q(CASE,'During the 2023 U.S. chemotherapy drug shortage, guidance generally prioritized which patients?','Those receiving curative-intent treatment',['Those receiving palliative-intent therapy','Those who requested the drug first','Those with the most insurance coverage'],'A','Prioritizing curable cancers aligns with maximizing long-term survival, a point the affirmative can use.',BH),
  q(CASE,'Who were prioritized first in most COVID-19 vaccine programs?','Health care workers and high-risk groups',['Children and teenagers in schools','Only volunteers from vaccine trials','People who could pay the most for doses'],'C','Programs balanced instrumental value with protecting those at highest risk of severe illness and death.',EMAN),
  q(CASE,'What did the WHO’s “3 by 5” initiative aim to do?','Treat 3 million people with HIV drugs by 2005',['Vaccinate 3 billion people by 2005','Build 3 new hospitals in each member nation','Cut drug prices by 5 percent'],'B','It raised hard questions about allocating limited antiretroviral therapy fairly in low-income countries.',BH),
  q(CASE,'The Oregon Health Plan in the 1990s used a ranked list of condition–treatment pairs. This is an example of:','Explicit macro-level rationing',['Implicit micro-level rationing','A lottery among all patients','First come, first served'],'D','Medicaid funded services above a cutoff line on a public list, making priorities visible and debatable.',BH),
  q(CASE,'The United Kingdom’s NICE often judges new treatments by which measure?','Cost per QALY gained',['Number of hospital beds','Physician seniority','Patients’ ages only'],'A','Treatments above a cost-per-QALY threshold are less likely to be recommended for the National Health Service.',BH),
  q(CASE,'Why does a “sickest first” rule cause concern on transplant waiting lists?','The sickest may gain fewer survival years',['The sickest always live the longest','It favors the healthiest candidates','It ignores medical urgency completely'],'C','Very ill candidates may have worse post-transplant survival, which illustrates the tension between urgency and benefit.',OPTN),
  q(AGE,'Levy’s research found that older adults with positive self-perceptions of aging lived about how much longer than those with negative ones?','7.5 years',['6 months','2 years','15 years'],'B','The study followed adults over decades; positive age beliefs were linked to longer survival.',LEVY),
  q(AGE,'Levy’s stereotype embodiment theory proposes that:','Age beliefs absorbed from culture affect health',['Aging is controlled entirely by genetics','Stereotypes affect only young people','Older adults ignore cultural messages'],'D','Beliefs internalized from childhood become self-relevant in old age and influence memory, cardiovascular stress and recovery.',LEVY),
  q(AGE,'How can the negative use Levy’s work against survival-based allocation?','Prognoses may reflect ageism, not biology',['Older patients always recover faster','Age beliefs never affect outcomes','All patients should be treated by age'],'A','If negative age beliefs worsen outcomes, predictions of shorter survival may become a self-fulfilling prophecy.',LEVY),
  q(AGE,'A prediction that causes itself to come true is called:','Self-fulfilling prophecy',['A false dilemma fallacy','A straw man argument','An ad hominem attack'],'C','Withholding care from patients predicted to do poorly can make poor outcomes more likely.',LEVY),
  q(AGE,'Levy describes women in Japan, where aging is viewed more positively, as reporting fewer of which menopause symptoms?','Hot flashes',['Headaches','Joint pain','Weight gain'],'B','Cultural views of aging appear to shape how people experience and report aging-related changes.',LEVY),
  q(AGE,'What does “biological age” refer to?','How old the body’s systems appear',['Years since birth','The age on official records','The age a person subjectively feels'],'D','Biological age can differ from chronological age, so age alone is a weak stand-in for prognosis.',LEVY),
  q(AGE,'Why can long-term survival criteria deepen health disparities?','Life expectancy reflects income and discrimination',['Every group has equal life expectancy','Survival is unrelated to living conditions','Disparities affect only acute illness'],'A','Groups with less access to care and more chronic disease may score lower, compounding existing inequities.',BH),
  q(AGE,'Which WHO report can the negative cite to show ageism harms health?','Global report on ageism',['World malaria report','Global tuberculosis report','World drug report'],'C','The 2021 report found ageism is widespread and linked to poorer physical and mental health.',LEVY),
  q(AGE,'How might the affirmative answer civil rights concerns about age and disability?','The rules bar stereotypes, not evidence',['Civil rights laws do not apply to hospitals','Age should be the only criterion used','Disability must always lower priority'],'B','The affirmative can argue individualized clinical evidence is allowed while blanket exclusions are not.',EMAN),
  q(AGE,'Daniel Callahan’s book Setting Limits (1987) proposed what?','Age-based limits on life-extending care',['Ending public funding for child care','Allocating all hospital care by lottery','Removing all limits on spending'],'D','His argument for age-based limits is a classic, controversial example of age-based rationing.',BH)
 ],409)
};
